  slug: "bayern",
  land: "DE",
  name: "Bayern",
  inName: "in Bayern",
  kurz: "BY",
  seoTitel: "Solarpark & Agri-PV Bayern: Pacht, Recht | ÖkoInvest",
  beschreibung:
